//! `emit_env_ibl` — prints the HLSL environment-arm leaves generated by tracing
//! `boyko_shaderdsl::ibl`'s generic bodies over the `Emit` backend (`feature = "emit"`): the span
//! `crates/boyko_rhi_vulkan/shaders/env_ibl.hlsli` carries between its
//! `// === GENERATED env_ibl BEGIN/END ===` sentinels (IBL1 R1, `ibl1/cut.md` C10).
//!
//! It PRINTS to stdout; the splice and the re-DXC of the 20 `-D REFL=1` rows are by hand
//! (`docs/SHADER-VARIANT-MANIFEST.md`'s REFL section), and `boyko_rhi_vulkan/tests/
//! env_ibl_edsl_sync.rs` fails on a committed span that differs from this output.
//!
//! Run: `cargo run -p boyko_shaderdsl --features emit --bin emit_env_ibl`

fn main() {
    print!("{}", boyko_shaderdsl::emit::emit_hlsl_env_ibl());
}
